      "title": "From Static to Dynamic: Benchmarking Real-World Code Review with MCR-Bench",
      "url": "https://arxiv.org/abs/2608.27442v1",
      "pdfUrl": "https://arxiv.org/pdf/2608.27442v1",
      "source": "arXiv",
