        "id": "arxiv:2608.27402v1",
        "title": "How Language Models Organize and Structure Moral Knowledge",
        "url": "https://arxiv.org/abs/2608.27402v1",
        "pdfUrl": "https://arxiv.org/pdf/2608.27402v1",
        "source": "arXiv",
        "points": 0,
